/* timerfd_gettime(3) - Retrieve current timer state */
#include <sys/timerfd.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

// Helper to convert timespec to milliseconds for printing
long timespec_to_ms(const struct timespec *ts) {
    return ts->tv_sec * 1000 + ts->tv_nsec / 1000000;
}

int main() {
    int tfd;
    struct itimerspec new_value, curr_value;
    int initial_time_sec = 5;

    // 1. Create the timer file descriptor using a monotonic clock
    tfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (tfd == -1) {
        perror("timerfd_create");
        return 1;
    }

    // Set initial expiration time to 5 seconds (one-shot timer)
    memset(&new_value, 0, sizeof(new_value));
    new_value.it_value.tv_sec = initial_time_sec;

    // 2. Arm the timer
    if (timerfd_settime(tfd, 0, &new_value, NULL) == -1) {
        perror("timerfd_settime");
        close(tfd);
        return 1;
    }

    printf("Timer armed for %d seconds.\n", initial_time_sec);

    // 3. Retrieve the current timer setting immediately
    if (timerfd_gettime(tfd, &curr_value) == -1) {
        perror("timerfd_gettime");
        close(tfd);
        return 1;
    }

    long remaining_ms = timespec_to_ms(&curr_value.it_value);
    long interval_ms = timespec_to_ms(&curr_value.it_interval);

    printf("--- Initial Timer State ---\n");
    printf("Remaining until expiration (ms): %ld\n", remaining_ms);
    printf("Repetitive interval (ms): %ld\n", interval_ms);

    sleep(1); // Wait for 1 second

    // 4. Retrieve the timer state again after a delay
    if (timerfd_gettime(tfd, &curr_value) == -1) {
        perror("timerfd_gettime after sleep");
        close(tfd);
        return 1;
    }

    remaining_ms = timespec_to_ms(&curr_value.it_value);
    printf("\nAfter 1 second delay:\n");
    printf("Remaining until expiration (ms): %ld\n", remaining_ms);

    close(tfd);
    return 0;
}
